import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CcJ8wlZS.js";const g=JSON.parse('{"title":"Machine-Readable Contract","description":"Lint codes, catalog.json, CI consumption","frontmatter":{"type":"index","title":"Machine-Readable Contract","description":"Lint codes, catalog.json, CI consumption","created":"2026-09-19T00:00:00.000Z","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"machine-contract.md","filePath":"machine-contract.md"}'),c={name:"machine-contract.md"};function d(i,e,n,r,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="machine-readable-contract" tabindex="-1">Machine-Readable Contract <a class="header-anchor" href="#machine-readable-contract" aria-label="Permalink to &quot;Machine-Readable Contract&quot;">​</a></h1><p>Everything the fabric validates and catalogs is available in JSON, so CI and agent harnesses can consume it without parsing prose:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # errors/warnings with code + page + message, ok flag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/rebuild-index.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # writes registry/catalog.json (catalog with ids, types, scopes, statuses)</span></span></code></pre></div><p>The lint report codes are stable: <code>FRONTMATTER</code>, <code>BROKEN-LINK</code>, <code>SCOPE</code>, <code>REVIEW-AFTER</code>, <code>CLAIM</code>, <code>CONCEPT</code>, <code>PATTERN</code>, <code>DUP-ID</code>, <code>SOURCE</code>, <code>SOURCE-DRIFT</code>, <code>SYNC-CONFLICT</code>, <code>ORPHAN</code>, <code>LLM-CONFIG</code>, <code>GENERATED</code>, <code>STALE-AFTER</code>, <code>TRUST-TIER</code>. <code>registry/catalog.json</code> carries every cataloged page with its <code>id</code>, <code>type</code>, <code>scope</code>, <code>status</code>, <code>maturity</code>, <code>review_after</code>, and <code>last_verified</code> — a deterministic, auditable answer to &quot;what knowledge exists and how fresh is it.&quot;</p><p><strong>Checks the contract enforces:</strong></p><table tabindex="0"><thead><tr><th>Check</th><th>Meaning</th></tr></thead><tbody><tr><td><code>SCOPE</code></td><td>frontmatter <code>scope:</code> must match the path-implied scope (<code>global/</code> <code>domains/</code> <code>projects/</code>) — precedence comes from scope, so scope lies are errors</td></tr><tr><td><code>REVIEW-AFTER</code></td><td>pages with a past <code>review_after</code> date are flagged stale (warning; message shows days overdue) — staleness is detected, not forgotten</td></tr><tr><td><code>SYNC-CONFLICT</code></td><td>unresolved team-sync conflicts block commit/push</td></tr><tr><td><code>SOURCE-DRIFT</code></td><td>a captured source&#39;s sha256 changed without re-ingest</td></tr></tbody></table><hr>`,7)])])}const m=t(c,[["render",d]]);export{g as __pageData,m as default};
